from html import escape

def render(path,port):
    kind=path.rsplit('/',1)[-1]
    if '/listing/' in path:
        return f'<!doctype html><title>Fixture listing</title><h1>Software Engineer — {escape(kind)}</h1><a target="_blank" href="http://127.0.0.1:{port}/fixtures/form/{escape(kind)}">Apply now</a>'
    if kind=='expired':return '<title>Expired</title><h1>This job is no longer available</h1>'
    if kind=='login':return '<title>Login fixture</title><h1>Sign in to apply</h1><label>Password<input type="password"></label><p>Fixture login blocker. Do not enter a real password.</p>'
    common='<label>Full name<input name="name" aria-label="Full name" required></label><label>Email<input type="email" required></label>'
    upload='''<label>Resume<input type="file" accept=".pdf,.docx" required onchange="const f=this.files[0]; if(f) f.arrayBuffer().then(b=>fetch('/fixtures/upload',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Filename':f.name},body:b})).then(r=>r.json()).then(r=>{document.querySelector('#receipt').textContent=r.accepted?'Uploaded and accepted: '+r.name:'Invalid document';})"></label><p id="receipt" role="status"></p>'''
    extra=''
    if kind=='missing':extra='<label>Desired salary<input required></label><label><input type="checkbox" required>I agree to terms</label>'
    if kind=='custom':extra='<label id="country-label">Preferred location</label><div role="combobox" tabindex="0" aria-labelledby="country-label" aria-controls="choices" aria-required="true" aria-expanded="false" onclick="this.setAttribute(\'aria-expanded\',\'true\');document.querySelector(\'#choices\').hidden=false">Choose location</div><div id="choices" hidden><button type="button" role="option" onclick="document.querySelector(\'[role=combobox]\').setAttribute(\'aria-valuetext\',\'Remote\');this.parentNode.hidden=true">Remote</button></div>'
    if kind=='radio':extra='<fieldset><legend>Contact preference</legend><label>Email preference<input type="radio" name="contact" value="Email" required></label><label>Phone preference<input type="radio" name="contact" value="Phone" required></label></fieldset><label>Country<select required><option value="">Choose</option><option>Canada</option><option>United States</option></select></label>'
    if kind=='repeated':extra=''.join('<fieldset><legend>Education</legend><label>School<input required></label><label>Degree<input required></label><label>Start date<input type="date" required></label></fieldset>' for _ in range(2))
    if kind=='guard':common='<label>Full name<input required onchange="this.form.requestSubmit()"></label><label>Email<input type="email" required></label>'
    body=common+upload+extra
    if kind=='multi':body='<section id="first">'+common+'<button type="button" data-jobprep-next onclick="document.querySelector(\'#first\').hidden=true;document.querySelector(\'#second\').hidden=false;this.remove()">Next: resume</button></section><section id="second" hidden>'+upload+'<label>Portfolio<input></label></section>'
    return '''<!doctype html><html data-jobprep-fixture="'''+escape(kind)+'''"><meta charset="utf-8"><title>Job Prep fixture — '''+escape(kind)+'''</title><style>body{font:17px system-ui;max-width:700px;margin:50px auto;background:#f4f6f5;color:#183832}label{display:block;margin:18px 0}input,select{display:block;padding:9px;width:90%;font:inherit}input[type=checkbox],input[type=radio]{width:auto}button{padding:10px;font:inherit}fieldset{margin:20px 0}[hidden]{display:none!important}</style><h1>Application fixture: '''+escape(kind)+'''</h1><p>Synthetic data only. This is an ordinary, editable Safari tab.</p><form onsubmit="event.preventDefault();window.submitAttempts++;document.getElementById('submit-count').textContent=window.submitAttempts">'''+body+'''<button type="submit">Submit application</button></form><p>Final submission attempts: <strong id="submit-count">0</strong></p><script>window.submitAttempts=0</script></html>'''
